<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal(); $pdo=db();$pageTitle='Produtos';$q=trim($_GET['q']??'');$cat=(int)($_GET['categoria_id']??0);$sql='SELECT p.*,c.nome categoria_nome FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id WHERE (p.nome LIKE ? OR p.codigo LIKE ? OR p.codigo_barras LIKE ?)';$args=array_fill(0,3,'%'.$q.'%');if($cat){$sql.=' AND p.categoria_id=?';$args[]=$cat;}$sql.=' ORDER BY p.ativo DESC,p.nome';$st=$pdo->prepare($sql);$st->execute($args);$rows=$st->fetchAll();$cats=$pdo->query('SELECT * FROM categorias WHERE ativo=1 ORDER BY nome')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$pdo->prepare('UPDATE produtos SET ativo=CASE ativo WHEN 1 THEN 0 ELSE 1 END,atualizado_em=? WHERE id=?')->execute([now(),$id]);log_action('ativação/desativação','produtos',$id);flash('success','Status do produto atualizado.');redirect('index.php');}
include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><div><h1>Produtos</h1></div><a class="btn primary" href="form.php">＋ Novo produto</a></div><div class="card"><form class="search-row" method="get"><input name="q" value="<?=e($q)?>" placeholder="Nome, código ou código de barras"><select name="categoria_id"><option value="0">Todas as categorias</option><?php foreach($cats as $c): ?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['nome'])?></option><?php endforeach; ?></select><button class="btn secondary">Filtrar</button></form></div><div class="card" style="margin-top:16px"><div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['codigo'])?></td><td><strong><?=e($r['nome'])?></strong><div class="muted"><?=e($r['codigo_barras'])?></div></td><td><?=e($r['categoria_nome'])?></td><td><?=money($r['preco'])?></td><td><?=e($r['estoque'])?> <?=e($r['unidade'])?></td><td><?=status_badge($r['ativo']?'Ativo':'Inativo')?></td><td class="nowrap"><a class="btn small secondary" href="form.php?id=<?=$r['id']?>">Editar</a><form style="display:inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small <?=$r['ativo']?'danger':'secondary'?>"><?=$r['ativo']?'Desativar':'Ativar'?></button></form></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="7" class="empty">Nenhum produto encontrado.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
